#include "lz4_decompress.h"
#include <string.h>

/* Minimum match length */
#define MINMATCH 4

/* --- Helper: read a single byte --- */
static inline int read_u8(const uint8_t **p, const uint8_t *end, uint8_t *out) {
    if (*p >= end) return -1;
    *out = **p;
    (*p)++;
    return 0;
}

/* --- Helper: read a 16-bit little-endian value --- */
static inline int read_u16_le(const uint8_t **p, const uint8_t *end, uint16_t *out) {
    if (*p + 2 > end) return -1;
    *out = (uint16_t)(*p)[0] | ((uint16_t)(*p)[1] << 8);
    *p += 2;
    return 0;
}

/* --- Helper: read a variable-length encoded integer ---
 * When a nibble value is 15, additional bytes follow.
 * Each byte's value is added to the running total.
 * A byte value of 255 means another byte follows.
 * The 'base' parameter is the starting value.
 * Returns 0 on success, or -1 on error/overflow.
 */
static int read_varlen(const uint8_t **p, const uint8_t *end,
                       size_t base, size_t *out) {
    size_t total = base;
    uint8_t b;

    do {
        if (read_u8(p, end, &b) != 0) return -1;
        if (total > SIZE_MAX - (size_t)b) return -1;
        total += (size_t)b;
    } while (b == 255);

    *out = total;
    return 0;
}

/*
 * Decompress an LZ4 compressed block.
 *
 * Returns the number of decompressed bytes on success, or -1 on error.
 */
ssize_t lz4_block_decompress(const void *src, size_t src_size,
                              void *dst, size_t dst_capacity) {
    const uint8_t *ip;
    const uint8_t *iend;
    uint8_t *output_start;
    uint8_t *op;
    uint8_t *oend;

    if (src == NULL || dst == NULL) return -1;

    /* A valid block always contains at least the final token byte. */
    if (src_size == 0) return -1;

    ip = (const uint8_t *)src;
    iend = ip + src_size;
    output_start = (uint8_t *)dst;
    op = output_start;
    oend = output_start + dst_capacity;

    while (ip < iend) {
        uint8_t token;
        size_t lit_len;
        size_t match_len;
        uint16_t offset_u16;
        size_t offset;

        if (read_u8(&ip, iend, &token) != 0) return -1;

        /* Literal length is the high nibble. */
        lit_len = token >> 4;
        if (lit_len == 15) {
            if (read_varlen(&ip, iend, 15, &lit_len) != 0) return -1;
        }

        /* Copy literals and verify both input and output bounds. */
        if (lit_len > (size_t)(iend - ip)) return -1;
        if (lit_len > (size_t)(oend - op)) return -1;

        if (lit_len > 0) {
            memcpy(op, ip, lit_len);
            ip += lit_len;
            op += lit_len;
        }

        /* If the input is consumed after literals, this was the final sequence. */
        if (ip == iend) break;

        /* Every non-final sequence has a 16-bit little-endian offset. */
        if (read_u16_le(&ip, iend, &offset_u16) != 0) return -1;
        offset = (size_t)offset_u16;

        /* Offset zero is invalid, and the match source must already exist. */
        if (offset == 0) return -1;
        if (offset > (size_t)(op - output_start)) return -1;

        /* Match length is the low nibble plus MINMATCH, with optional extension. */
        match_len = token & 0x0F;
        if (match_len == 15) {
            if (read_varlen(&ip, iend, 15, &match_len) != 0) return -1;
        }
        if (match_len > SIZE_MAX - MINMATCH) return -1;
        match_len += MINMATCH;

        if (match_len > (size_t)(oend - op)) return -1;

        /* Copy byte-by-byte to correctly support overlapping matches. */
        {
            const uint8_t *match = op - offset;
            while (match_len > 0) {
                *op++ = *match++;
                match_len--;
            }
        }
    }

    return (ssize_t)(op - output_start);
}
