cat > /tmp/test_capacity.c <<'EOF'
#include "lz4_decompress.h"
#include <stdio.h>
#include <string.h>

int main(void) {
    unsigned char out[64];
    ssize_t n;

    /* Literal-only block: output "hello" (5 bytes). */
    {
        const unsigned char in[] = {0x50, 'h','e','l','l','o'};
        memset(out, 0, sizeof(out));
        n = lz4_block_decompress(in, sizeof(in), out, 5);
        if (n != 5 || memcmp(out, "hello", 5) != 0) return 1;
        n = lz4_block_decompress(in, sizeof(in), out, 4);
        if (n != -1) return 2;
    }

    /* Match block producing "aaaaaa" (6 bytes). */
    {
        const unsigned char in[] = {0x10, 'a', 0x01, 0x00, 0x00};
        memset(out, 0, sizeof(out));
        n = lz4_block_decompress(in, sizeof(in), out, 6);
        if (n != 6 || memcmp(out, "aaaaaa", 6) != 0) return 3;
        n = lz4_block_decompress(in, sizeof(in), out, 5);
        if (n != -1) return 4;
    }

    /* Empty block with zero capacity. */
    {
        const unsigned char in[] = {0x00};
        n = lz4_block_decompress(in, sizeof(in), out, 0);
        if (n != 0) return 5;
    }

    puts("capacity tests passed");
    return 0;
}
